#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
cd "$REPO_ROOT"

echo "=== Jingcai Stage3 Canonical v1.0.1 updater ==="
echo "Repo: $REPO_ROOT"

git pull --ff-only origin main

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

TMP_DIR="$TMP" python3 - <<'PY2'
from pathlib import Path
import base64, os
payload = """"""
Path(os.environ["TMP_DIR"]).joinpath("skill.zip").write_bytes(base64.b64decode(payload))
PY2

unzip -q "$TMP/skill.zip" -d "$TMP/unpacked"
SRC="$TMP/unpacked/Jingcai_Stage3_Canonical_Skill_v1.0.1"
TARGET="skills/jingcai-stage3"

if [ ! -f "$SRC/SKILL.md" ]; then
  echo "ERROR: packaged Skill missing SKILL.md"
  exit 1
fi

rm -rf "$TARGET"
mkdir -p "$TARGET"
cp -R "$SRC/." "$TARGET/"

python3 "$TARGET/runtime/validate_skill.py"

echo "=== Manifest ==="
cat "$TARGET/SKILL_MANIFEST.json"

# Remove updater itself if it was uploaded to the repository root.
SELF_BASE="$(basename "$0")"
if git ls-files --error-unmatch "$SELF_BASE" >/dev/null 2>&1; then
  git rm -f "$SELF_BASE" >/dev/null
elif [ -f "$SELF_BASE" ]; then
  rm -f "$SELF_BASE"
fi

git add -A "$TARGET"

if git diff --cached --quiet; then
  echo "No Skill changes to commit. v1.0.1 may already be installed."
else
  git commit -m "Upgrade Jingcai Stage3 Canonical Skill to v1.0.1"
  git push origin main
fi

echo "=== FINAL VERIFY ==="
python3 "$TARGET/runtime/validate_skill.py"
echo "=== DONE: Jingcai Stage3 Canonical v1.0.1 ==="
